using Umss.BloodOrgansDonationApp.Models.Entities;

namespace Umss.BloodOrgansDonationApp.Models
{
    /// <summary>
    /// A donation post of the feed. When it has a <see cref="Status"/> it is also a clinical
    /// donation request (US-API-01/02): the same row feeds the mobile feed and the portal board,
    /// so both always show the same data. Plain posts leave the clinical fields empty.
    /// </summary>
    public class DonationPost
    {
        public Guid Id { get; set; }

        /// <summary>Readable number, shown as REQ-{Folio}. Generated by the database.</summary>
        public int Folio { get; set; }

        public BloodType BloodType { get; set; }

        public Guid BloodTypeId { get; set; }

        /// <summary>Replaces the old Priority flag: Priority true became <see cref="Urgency.Priority"/>.</summary>
        public Urgency Urgency { get; set; }

        public DonationType DonationType { get; set; }

        public Guid DonationTypeId { get; set; }

        public User? User { get; set; }

        public Guid? UserId { get; set; }

        public DonationCenter? DonationCenter { get; set; }

        public Guid? DonationCenterId { get; set; }

        public string Title { get; set; } = string.Empty;

        public required string Description { get; set; }

        public required string Image { get; set; }

        public DateTime CreatedAt { get; set; }

        public DateTime UpdatedAt { get; set; }

        public ICollection<Comment> Comments { get; set; }

        // Clinical request (US-API-01). Patient data is shown only to clinical staff, admins and the author.

        public BloodComponent? Component { get; set; }

        /// <summary>Clinical patient identifier, e.g. "PX-4912". Never the patient's name.</summary>
        public string? PatientCode { get; set; }

        public int? PatientAge { get; set; }

        public string? Diagnosis { get; set; }

        /// <summary>Hospital service, e.g. "Quirofano Central 3".</summary>
        public string? Service { get; set; }

        /// <summary>Bed or room, e.g. "UCI-04".</summary>
        public string? Bed { get; set; }

        /// <summary>Expediente clinico.</summary>
        public string? MedicalRecord { get; set; }

        public string? CoordinationPhone { get; set; }

        public int? UnitsRequired { get; set; }

        public int UnitsCovered { get; set; }

        /// <summary>UTC moment the units are needed by.</summary>
        public DateTime? Deadline { get; set; }

        // Triage phase (US-API-02).

        /// <summary>Null on plain posts. Concurrency token: two coordinators can't both move the same card.</summary>
        public RequestStatus? Status { get; set; }

        public DateTime? StatusChangedAt { get; set; }

        public Guid? StatusChangedById { get; set; }

        public User? StatusChangedBy { get; set; }

        public ICollection<DonationRequestStatusChange> StatusChanges { get; set; } = new List<DonationRequestStatusChange>();
    }
}
